<div class="interactive-wrapper"><div class="card shadow-sm border-0 mb-4" style="border-radius:24px;background:#fff;word-break:break-word"><div class="bg-white border-bottom-0 py-4 px-4" style="border-radius:24px 24px 0 0"><div class="d-flex align-items-center justify-content-between flex-wrap gap-2"><div class="d-flex align-items-center"><div style="width:48px;height:48px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:1.25rem;background:#eef2ff"><i class="fas fa-coins text-primary"></i></div><div class="ms-3"><h5 class="mb-0 fw-bold text-dark">Penny Drop Impact</h5><p class="text-muted small mb-0">Calculate terminal velocity and impact force of a falling penny</p></div></div><button class="btn btn-sm rounded-pill px-3" id="btn-reset" style="background:#f1f5f9;font-weight:600"><i class="fas fa-undo me-1"></i>Reset</button></div></div><div class="px-4 pb-4" style="overflow-x:auto"><div class="row g-3"><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Drop Height (m)</label><input type="number" id="in-h" class="form-control form-control-lg" value="381" step="1"><div class="form-text">Empire State=381m</div></div><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Penny Mass (g)</label><input type="number" id="in-m" class="form-control form-control-lg" value="2.5" step="0.1"></div><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Initial Velocity (m/s)</label><input type="number" id="in-v0" class="form-control form-control-lg" value="0" step="0.1"></div><div class="col-12"><div class="form-check form-switch"><input class="form-check-input" type="checkbox" id="in-air" checked><label class="form-check-label small fw-bold text-secondary" for="in-air">Include Air Resistance</label></div></div></div><div class="mt-4 text-center"><button class="btn btn-primary btn-lg rounded-pill px-5 shadow-sm" id="btn-calc" style="min-width:260px;max-width:100%"><i class="fas fa-calculator me-2"></i>Calculate</button></div><div class="mt-3 p-3 rounded-4 border" style="background:#f8fafc"><p class="mb-0 small text-muted"><i class="fas fa-info-circle text-primary me-2"></i><b>Formula:</b> v = √(2gh) without air; Terminal v ≈ 11 m/s with drag</p></div></div></div><div id="res" class="card shadow-sm border-0 d-none mb-4" style="border-radius:24px;background:#fff;word-break:break-word"><div class="bg-white border-bottom-0 py-4 px-4" style="border-radius:24px 24px 0 0"><div class="d-flex align-items-center justify-content-between flex-wrap gap-2"><div class="d-flex align-items-center"><div style="width:48px;height:48px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:1.25rem;background:#ecfdf5"><i class="fas fa-check-circle text-success"></i></div><div class="ms-3"><h5 class="mb-0 fw-bold text-dark">Result</h5></div></div><button class="btn btn-success btn-sm rounded-pill px-4 shadow-sm" id="btn-copy"><i class="fas fa-copy me-1"></i>Copy</button></div></div><div class="px-4 pb-4" style="overflow-x:auto"><div class="p-4 rounded-4 bg-light border text-center mb-3"><div class="small fw-bold text-uppercase text-muted mb-1">RESULT</div><div class="display-4 fw-bold text-dark" id="out-main">—</div><div class="small text-muted fw-bold" id="out-unit"></div></div><div id="out-detail" class="row g-3 mb-3"></div><div class="p-4 rounded-4 bg-light border"><h6 class="fw-bold mb-2 small text-uppercase text-muted"><i class="fas fa-lightbulb text-warning me-2"></i>Insights</h6><div id="out-ins" class="small"></div></div></div></div></div><style>.form-control-lg,.form-select-lg{border:1.5px solid #e2e8f0;border-radius:12px;font-size:1.05rem;padding:.75rem 1rem}.form-control:focus,.form-select:focus{border-color:#4f46e5;box-shadow:0 0 0 4px rgba(79,70,229,.1)}</style><script>document.addEventListener("DOMContentLoaded",function(){document.getElementById("btn-calc").addEventListener("click",function(){var h=parseFloat(document.getElementById("in-h").value)||0,m=(parseFloat(document.getElementById("in-m").value)||2.5)/1000,v0=parseFloat(document.getElementById("in-v0").value)||0,air=document.getElementById("in-air").checked;var g=9.81;var vNoAir=Math.sqrt(v0*v0+2*g*h);var vt=11;var v=air?Math.min(vNoAir,vt):vNoAir;var ke=0.5*m*v*v;var t=air?(vt/g)*Math.acosh(Math.exp(g*h/(vt*vt))):Math.sqrt(2*h/g);document.getElementById("out-main").textContent=v.toFixed(2);document.getElementById("out-unit").textContent="m/s impact velocity";document.getElementById("out-detail").innerHTML='<div class="col-3"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Velocity</div><div class="h5 fw-bold mb-0 text-primary">'+v.toFixed(2)+' m/s</div></div></div><div class="col-3"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">KE</div><div class="h5 fw-bold mb-0 text-danger">'+ke.toFixed(4)+' J</div></div></div><div class="col-3"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Fall Time</div><div class="h5 fw-bold mb-0 text-info">'+t.toFixed(2)+' s</div></div></div><div class="col-3"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">km/h</div><div class="h5 fw-bold mb-0 text-warning">'+(v*3.6).toFixed(1)+'</div></div></div>';var ins=["Impact at <b>"+v.toFixed(2)+" m/s ("+(v*3.6).toFixed(1)+" km/h)</b>"];if(air)ins.push("Terminal velocity limits speed to ~11 m/s due to drag.");ins.push("Kinetic energy: <b>"+ke.toFixed(4)+" J</b> — "+(ke<0.05?"harmless":"noticeable but not deadly"));document.getElementById("out-ins").innerHTML='<ul class="list-unstyled mb-0">'+ins.map(function(x){return'<li class="mb-2"><i class="fas fa-check-circle text-success me-2"></i>'+x+"</li>";}).join("")+"</ul>";document.getElementById("res").classList.remove("d-none");});document.getElementById("btn-reset").addEventListener("click",function(){document.getElementById("in-h").value=381;document.getElementById("in-m").value=2.5;document.getElementById("in-v0").value=0;document.getElementById("res").classList.add("d-none");});document.getElementById("btn-copy").addEventListener("click",function(){navigator.clipboard.writeText("Impact: "+document.getElementById("out-main").textContent+" m/s");var b=this;b.innerHTML="Copied!";setTimeout(function(){b.innerHTML="<i class=\"fas fa-copy me-1\"></i>Copy";},2e3);});});</script>